#[link(name = "kernel32")]
extern "system" {
    fn GetStdHandle(nStdHandle: i32) -> i32;
    fn WriteConsoleW(
        hConsoleOutput: i32,
        lpBuffer: *const u16,
        numberOfCharsToWrite: u32,
        lpNumberOfCharsWritten: *mut u32,
        lpReserved: *const std::ffi::c_void,
    ) -> i32;
}

fn syscall(message: String) -> io::Result<()> {
    let msg: Vec<u16> = message.encode_utf16().collect();
    let msg_ptr = msg.as_ptr();
    let len = msg.len() as u32;
    let mut output: u32 = 0;

    let handle = unsafe { GetStdHandle(-11) };
    if handle == -1 {
        // GetStdHandle returns -1 on error, but the specific error code is often
        // available via other means or you can just return a generic error.
        // However, for functions that return a DWORD error code:
        return Err(io::Error::last_os_error()); // Or handle specifically
    }

    let res = unsafe {
        WriteConsoleW(
            handle,
            msg_ptr,
            len,
            &mut output,
            std::ptr::null()
        )
    };

    if res != 0 {
        // 'res' is the Windows error code (DWORD).
        // Use from_raw_os_error to convert it to a standard io::Error.
        return Err(io::Error::from_raw_os_error(res as i32));
    }

    Ok(())
}
```

The key change is using `io::Error::from_raw_os_error(res as i32)` instead of `io::Error::last_os_error()` when you have a specific error code from a Windows API call.

